{"content":"import networkx as nx,itertools,z3,json,time

def embeds(H,FA,FB,timeout=10000):
    # Each side has unlimited independent bulk vertices, plus its finite internal graph.
    nA=len(FA)+1;nB=len(FB)+1;cut=nA
    xa={v:i+1 for i,v in enumerate(FA)};xb={v:i+cut+1 for i,v in enumerate(FB)}
    edges=[(xa[u],xa[v]) for u,v in FA.edges()]+[(xb[u],xb[v]) for u,v in FB.edges()]
    s=z3.Solver();s.set(timeout=timeout)
    xs=[z3.Int('x'+str(i)) for i in H]
    for x in xs:s.add(x>=0,x<nA+nB)
    for label in list(xa.values())+list(xb.values()):s.add(z3.AtMost(*[x==label for x in xs],1))
    for u,v in H.edges():
        s.add(z3.Or((xs[u]<cut)!=(xs[v]<cut),*[z3.Or(z3.And(xs[u]==a,xs[v]==b),z3.And(xs[u]==b,xs[v]==a)) for a,b in edges]))
    ans=s.check()
    if ans==z3.unknown:print('unknown',len(H),flush=True);return None
    return ans==z3.sat

empty=nx.empty_graph(0);tri=nx.complete_graph(3);edge=nx.path_graph(2)
triedge=nx.disjoint_union(tri,edge);p3s=nx.disjoint_union(nx.path_graph(3),nx.path_graph(3))
pairs=list(itertools.combinations(range(3),2))
start=time.time()
for ca in range(64):
 H=nx.Graph();H.add_nodes_from(range(7))
 for i in range(3):H.add_edges_from([(0,1+i),(0,4+i),(1+i,4+i)])
 k=0
 for offset in [1,4]:
  for i,j in pairs:
   count=3 if ca>>k&1 else 1;k+=1
   new=list(range(len(H),len(H)+count))
   nx.add_path(H,[offset+i]+new+[offset+j])
 if embeds(H,triedge,empty):continue
 if embeds(H,tri,tri):continue
 print('candidate',ca,'n',len(H),flush=True)
 p=embeds(H,p3s,empty);q=embeds(H,triedge,edge)
